META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–11: ಧೃತರಾಷ್ಟ್ರನ ಪ್ರಶ್ನೆ; ದುರ್ಯೋಧನ ಎರಡೂ ಸೇನೆಗಳ ವೀರರನ್ನು ದ್ರೋಣರಿಗೆ ಹೆಸರಿಸುತ್ತಾನೆ; 12–19: ಶಂಖಗಳ ಘೋಷ; 20–27: ಅರ್ಜುನ ರಥವನ್ನು ಎರಡೂ ಸೇನೆಗಳ ನಡುವೆ ನಿಲ್ಲಿಸಲು ಹೇಳಿ ಎದುರಿನಲ್ಲಿ ತನ್ನ ಬಂಧುಗಳನ್ನು ನೋಡುತ್ತಾನೆ; 28–46: ಅರ್ಜುನನ ದುಃಖ ಮತ್ತು ಯುದ್ಧ ಮಾಡಬಾರದು ಎಂಬ ಅವನ ವಾದಗಳು; 47: ಅವನು ಬಿಲ್ಲನ್ನು ಕೆಳಗಿಟ್ಟು ಕುಳಿತುಬಿಡುತ್ತಾನೆ.',
)
T = {
2: 'ಸಂಜಯ ಹೇಳಿದನು: ಯುದ್ಧಕ್ಕೆ ಸಜ್ಜಾಗಿ ನಿಂತ ಪಾಂಡವರ ಸೇನೆಯನ್ನು ನೋಡಿ, ರಾಜ ದುರ್ಯೋಧನ ತನ್ನ ಗುರು ದ್ರೋಣರ ಬಳಿ ಹೋಗಿ ಹೀಗೆ ಹೇಳಿದನು:',
3: 'ಹೇ ಆಚಾರ್ಯರೇ, ನಿಮ್ಮದೇ ಬುದ್ಧಿವಂತ ಶಿಷ್ಯನಾದ ದ್ರುಪದನ ಮಗ ವ್ಯೂಹದಲ್ಲಿ ಜೋಡಿಸಿರುವ ಪಾಂಡುಪುತ್ರರ ಈ ದೊಡ್ಡ ಸೇನೆಯನ್ನು ನೋಡಿ.',
4: 'ಇಲ್ಲಿ ಯುದ್ಧದಲ್ಲಿ ಭೀಮ ಮತ್ತು ಅರ್ಜುನರಿಗೆ ಸಮಾನರಾದ ವೀರರೂ ಮಹಾ ಬಿಲ್ಲುಗಾರರೂ ಇದ್ದಾರೆ: ಯುಯುಧಾನ, ವಿರಾಟ ಮತ್ತು ಮಹಾರಥಿ ದ್ರುಪದ;',
5: 'ಧೃಷ್ಟಕೇತು, ಚೇಕಿತಾನ ಮತ್ತು ವೀರನಾದ ಕಾಶಿರಾಜ; ಪುರುಜಿತ್, ಕುಂತಿಭೋಜ ಮತ್ತು ಮನುಷ್ಯರಲ್ಲಿ ಶ್ರೇಷ್ಠನಾದ ಶೈಬ್ಯ;',
6: 'ಪರಾಕ್ರಮಿ ಯುಧಾಮನ್ಯು ಮತ್ತು ವೀರ ಉತ್ತಮೌಜ, ಸುಭದ್ರೆಯ ಮಗ ಮತ್ತು ದ್ರೌಪದಿಯ ಮಕ್ಕಳು, ಇವರೆಲ್ಲರೂ ಮಹಾರಥಿಗಳು.',
7: 'ಹೇ ಬ್ರಾಹ್ಮಣಶ್ರೇಷ್ಠರೇ, ಈಗ ನಮ್ಮ ಸೇನೆಯ ನಾಯಕರನ್ನೂ ತಿಳಿಯಿರಿ. ನಿಮಗಾಗಿ ಅವರ ಹೆಸರುಗಳನ್ನು ಹೇಳುತ್ತೇನೆ.',
8: 'ನೀವು, ಭೀಷ್ಮ, ಕರ್ಣ ಮತ್ತು ಯುದ್ಧದಲ್ಲಿ ಸದಾ ಗೆಲ್ಲುವ ಕೃಪ; ಅಶ್ವತ್ಥಾಮ, ವಿಕರ್ಣ ಮತ್ತು ಸೋಮದತ್ತನ ಮಗ.',
9: 'ನನಗಾಗಿ ಪ್ರಾಣ ಕೊಡಲು ಸಿದ್ಧರಾದ, ಅನೇಕ ಆಯುಧಗಳನ್ನು ಹಿಡಿದ, ಯುದ್ಧದಲ್ಲಿ ಪರಿಣತರಾದ ಇನ್ನೂ ಅನೇಕ ವೀರರು ಇದ್ದಾರೆ.',
10: 'ಭೀಷ್ಮರು ಕಾಯುತ್ತಿರುವ ನಮ್ಮ ಸೇನೆ ಅಳತೆಗೆ ಮೀರಿದಂತೆ ಕಾಣುತ್ತದೆ, ಭೀಮ ಕಾಯುತ್ತಿರುವ ಅವರ ಸೇನೆ ಸೀಮಿತ. (ಕೆಲವು ವ್ಯಾಖ್ಯಾನಕಾರರು ಇದನ್ನು ವಿರುದ್ಧವಾಗಿ ಓದುತ್ತಾರೆ: ನಮ್ಮದು ಸಾಲದು, ಅವರದು ಸಾಕು.)',
11: 'ಆದ್ದರಿಂದ ನೀವೆಲ್ಲರೂ ಪ್ರತಿಯೊಂದು ವ್ಯೂಹದಲ್ಲೂ ನಿಮ್ಮ ನಿಮ್ಮ ಸ್ಥಾನಗಳಲ್ಲಿ ದೃಢವಾಗಿ ನಿಂತು, ಎಲ್ಲಕ್ಕಿಂತ ಮೊದಲು ಭೀಷ್ಮರನ್ನು ರಕ್ಷಿಸಬೇಕು.',
12: 'ದುರ್ಯೋಧನನಿಗೆ ಉತ್ಸಾಹ ತುಂಬಲು, ಕುರುಗಳಲ್ಲಿ ಹಿರಿಯರಾದ ಪ್ರತಾಪಿ ಪಿತಾಮಹ ಭೀಷ್ಮರು ಸಿಂಹದಂತೆ ಗರ್ಜಿಸಿ ಜೋರಾಗಿ ಶಂಖ ಊದಿದರು.',
13: 'ಆಗ ಶಂಖಗಳು, ನಗಾರಿಗಳು, ಡೋಲುಗಳು, ಢಕ್ಕೆಗಳು ಮತ್ತು ಕೊಂಬುಗಳು ಒಮ್ಮೆಲೇ ಮೊಳಗಿದವು, ಆ ಶಬ್ದ ಭಯಂಕರವಾಗಿತ್ತು.',
14: 'ಆಗ ಬಿಳಿ ಕುದುರೆಗಳನ್ನು ಕಟ್ಟಿದ ದೊಡ್ಡ ರಥದಲ್ಲಿ ಕುಳಿತಿದ್ದ ಶ್ರೀಕೃಷ್ಣ ಮತ್ತು ಅರ್ಜುನ ತಮ್ಮ ದಿವ್ಯ ಶಂಖಗಳನ್ನು ಊದಿದರು.',
15: 'ಶ್ರೀಕೃಷ್ಣ ಪಾಂಚಜನ್ಯವನ್ನು, ಅರ್ಜುನ ದೇವದತ್ತವನ್ನು ಊದಿದರು, ಭಯಂಕರ ಕಾರ್ಯಗಳ ಭೀಮ ತನ್ನ ದೊಡ್ಡ ಶಂಖ ಪೌಂಡ್ರವನ್ನು ಊದಿದನು.',
16: 'ಕುಂತಿಯ ಮಗ ರಾಜ ಯುಧಿಷ್ಠಿರ ಅನಂತವಿಜಯವನ್ನು ಊದಿದನು; ನಕುಲ ಮತ್ತು ಸಹದೇವ ಸುಘೋಷ ಮತ್ತು ಮಣಿಪುಷ್ಪಕಗಳನ್ನು ಊದಿದರು.',
17: 'ಉತ್ತಮ ಬಿಲ್ಲುಗಾರನಾದ ಕಾಶಿರಾಜ, ಮಹಾರಥಿ ಶಿಖಂಡಿ, ಧೃಷ್ಟದ್ಯುಮ್ನ, ವಿರಾಟ ಮತ್ತು ಸೋಲರಿಯದ ಸಾತ್ಯಕಿ,',
18: 'ದ್ರುಪದ, ದ್ರೌಪದಿಯ ಮಕ್ಕಳು ಮತ್ತು ಬಲಿಷ್ಠ ಬಾಹುಗಳ ಸುಭದ್ರೆಯ ಮಗ, ಎಲ್ಲರೂ ತಮ್ಮ ತಮ್ಮ ಶಂಖಗಳನ್ನು ಊದಿದರು, ಹೇ ರಾಜನೇ.',
19: 'ಆಕಾಶ ಮತ್ತು ಭೂಮಿಯಲ್ಲಿ ಪ್ರತಿಧ್ವನಿಸಿದ ಆ ಭಯಂಕರ ಶಬ್ದ ಧೃತರಾಷ್ಟ್ರನ ಮಕ್ಕಳ ಹೃದಯಗಳನ್ನು ನಡುಗಿಸಿತು.',
20: 'ಆಗ, ಆಯುಧಗಳು ಇನ್ನೇನು ಘರ್ಷಿಸಲಿದ್ದಾಗ, ಹನುಮಂತನ ಧ್ವಜವುಳ್ಳ ಅರ್ಜುನ ಸಿದ್ಧರಾಗಿ ನಿಂತ ಧೃತರಾಷ್ಟ್ರನ ಮಕ್ಕಳನ್ನು ನೋಡಿ ತನ್ನ ಬಿಲ್ಲನ್ನು ಎತ್ತಿದನು,',
21: 'ಮತ್ತು ಶ್ರೀಕೃಷ್ಣನಿಗೆ ಹೇಳಿದನು: "ಹೇ ಅಚ್ಯುತ, ನನ್ನ ರಥವನ್ನು ಎರಡೂ ಸೇನೆಗಳ ನಡುವೆ ನಿಲ್ಲಿಸು,',
22: 'ಯುದ್ಧ ಮಾಡುವ ಆಸೆಯಿಂದ ಇಲ್ಲಿ ನಿಂತಿರುವವರನ್ನು, ಈ ಯುದ್ಧದಲ್ಲಿ ನಾನು ಯಾರೊಂದಿಗೆ ಹೋರಾಡಬೇಕೋ ಅವರನ್ನು ನಾನು ನೋಡುವಂತೆ.',
23: 'ದುಷ್ಟಬುದ್ಧಿಯ ಧೃತರಾಷ್ಟ್ರನ ಮಗನನ್ನು ಮೆಚ್ಚಿಸಲು ಬಯಸಿ, ಯುದ್ಧಕ್ಕೆ ಸಿದ್ಧರಾಗಿ ಇಲ್ಲಿ ಸೇರಿರುವವರು ಯಾರು ಎಂದು ನೋಡಬೇಕು."',
24: 'ಸಂಜಯ ಹೇಳಿದನು: ಅರ್ಜುನ ಹೀಗೆ ಕೇಳಿದಾಗ, ಶ್ರೀಕೃಷ್ಣ ಆ ಶ್ರೇಷ್ಠ ರಥವನ್ನು ನಡೆಸಿ ಎರಡೂ ಸೇನೆಗಳ ನಡುವೆ ನಿಲ್ಲಿಸಿದನು,',
25: 'ಭೀಷ್ಮ, ದ್ರೋಣ ಮತ್ತು ಎಲ್ಲ ರಾಜರ ಎದುರು, ಮತ್ತು ಹೇಳಿದನು: "ಹೇ ಪಾರ್ಥ, ಇಲ್ಲಿ ಸೇರಿರುವ ಈ ಕುರುಗಳನ್ನು ನೋಡು."',
26: 'ಅಲ್ಲಿ ಅರ್ಜುನ ಎರಡೂ ಸೇನೆಗಳಲ್ಲಿ ನಿಂತಿದ್ದ ತಂದೆಯಂದಿರು, ಅಜ್ಜಂದಿರು, ಗುರುಗಳು, ಚಿಕ್ಕಪ್ಪ ಸೋದರಮಾವಂದಿರು, ಸಹೋದರರು, ಮಕ್ಕಳು, ಮೊಮ್ಮಕ್ಕಳು ಮತ್ತು ಗೆಳೆಯರನ್ನು ನೋಡಿದನು,',
27: 'ಮಾವಂದಿರು ಮತ್ತು ಹಿತೈಷಿಗಳನ್ನೂ ನೋಡಿದನು. ಅಲ್ಲಿ ನಿಂತಿದ್ದ ಈ ಎಲ್ಲ ಬಂಧುಗಳನ್ನು ನೋಡಿ,',
28: 'ಅರ್ಜುನ ಆಳವಾದ ಕರುಣೆಯಿಂದ ತುಂಬಿ ದುಃಖದಿಂದ ಹೇಳಿದನು: "ಹೇ ಕೃಷ್ಣ, ಯುದ್ಧದ ಆಸೆಯಿಂದ ಇಲ್ಲಿ ನಿಂತಿರುವ ನನ್ನವರನ್ನೇ ನೋಡಿ,',
29: 'ನನ್ನ ಅಂಗಗಳು ಸೋಲುತ್ತಿವೆ, ಬಾಯಿ ಒಣಗುತ್ತಿದೆ, ದೇಹ ನಡುಗುತ್ತಿದೆ ಮತ್ತು ರೋಮಾಂಚನವಾಗುತ್ತಿದೆ.',
30: 'ಗಾಂಡೀವ ಬಿಲ್ಲು ಕೈಯಿಂದ ಜಾರುತ್ತಿದೆ, ಚರ್ಮ ಉರಿಯುತ್ತಿದೆ, ನಾನು ಸ್ಥಿರವಾಗಿ ನಿಲ್ಲಲಾರೆ, ನನ್ನ ಮನಸ್ಸು ತಿರುಗುತ್ತಿದೆ.',
31: 'ಹೇ ಕೇಶವ, ನನಗೆ ಅಪಶಕುನಗಳು ಕಾಣುತ್ತಿವೆ, ಯುದ್ಧದಲ್ಲಿ ನನ್ನವರನ್ನೇ ಕೊಲ್ಲುವುದರಲ್ಲಿ ಯಾವ ಒಳಿತೂ ಕಾಣುತ್ತಿಲ್ಲ.',
32: 'ಹೇ ಕೃಷ್ಣ, ನನಗೆ ಗೆಲುವೂ ಬೇಡ, ರಾಜ್ಯವೂ ಬೇಡ, ಸುಖಗಳೂ ಬೇಡ. ಹೇ ಗೋವಿಂದ, ರಾಜ್ಯದಿಂದ, ಭೋಗಗಳಿಂದ, ಜೀವನದಿಂದಲೂ ನಮಗೇನು ಪ್ರಯೋಜನ,',
33: 'ಯಾರಿಗಾಗಿ ನಾವು ರಾಜ್ಯ ಮತ್ತು ಸುಖಗಳನ್ನು ಬಯಸುತ್ತೇವೋ, ಅವರೇ ಪ್ರಾಣ ಮತ್ತು ಸಂಪತ್ತನ್ನು ತ್ಯಜಿಸಲು ಸಿದ್ಧರಾಗಿ ಇಲ್ಲಿ ಯುದ್ಧದಲ್ಲಿ ನಿಂತಿರುವಾಗ?',
34: 'ಗುರುಗಳು, ತಂದೆಯಂದಿರು, ಮಕ್ಕಳು, ಅಜ್ಜಂದಿರು, ಸೋದರಮಾವಂದಿರು, ಮಾವಂದಿರು, ಮೊಮ್ಮಕ್ಕಳು, ಭಾವಮೈದುನರು ಮತ್ತು ಇತರ ಬಂಧುಗಳು.',
35: 'ಹೇ ಮಧುಸೂದನ, ಅವರು ನನ್ನನ್ನು ಕೊಂದರೂ ನಾನು ಅವರನ್ನು ಕೊಲ್ಲಲು ಬಯಸುವುದಿಲ್ಲ, ಮೂರು ಲೋಕಗಳ ಆಳ್ವಿಕೆಗಾಗಿಯೂ ಅಲ್ಲ, ಈ ಭೂಮಿಗಾಗಿ ಇನ್ನೆಲ್ಲಿ?',
36: 'ಹೇ ಜನಾರ್ದನ, ಧೃತರಾಷ್ಟ್ರನ ಮಕ್ಕಳನ್ನು ಕೊಂದು ನಮಗೆ ಯಾವ ಸಂತೋಷ ಸಿಗಬಹುದು? ಈ ಆಕ್ರಮಣಕಾರರನ್ನು ಕೊಂದರೆ ನಮಗೆ ಪಾಪ ಮಾತ್ರ ಬರುತ್ತದೆ.',
37: 'ಆದ್ದರಿಂದ ನಮ್ಮದೇ ಕುಟುಂಬದವರಾದ ಧೃತರಾಷ್ಟ್ರನ ಮಕ್ಕಳನ್ನು ನಾವು ಕೊಲ್ಲಬಾರದು. ಹೇ ಮಾಧವ, ನಮ್ಮವರನ್ನೇ ಕೊಂದು ನಾವು ಹೇಗೆ ಸುಖವಾಗಿರಲು ಸಾಧ್ಯ?',
38: 'ಲೋಭದಿಂದ ಕುರುಡಾದ ಅವರು ಕುಲವನ್ನು ನಾಶಮಾಡುವುದರಲ್ಲಿ ತಪ್ಪನ್ನೂ, ಮಿತ್ರರಿಗೆ ದ್ರೋಹ ಮಾಡುವುದರಲ್ಲಿ ಪಾಪವನ್ನೂ ಕಾಣದಿದ್ದರೂ,',
39: 'ಹೇ ಜನಾರ್ದನ, ಕುಲನಾಶದ ತಪ್ಪನ್ನು ಕಾಣಬಲ್ಲ ನಾವು ಈ ಪಾಪದಿಂದ ಏಕೆ ದೂರ ಸರಿಯಬಾರದು?',
40: 'ಕುಲ ನಾಶವಾದಾಗ ಅದರ ಪ್ರಾಚೀನ ಸಂಪ್ರದಾಯಗಳು ಕಳೆದುಹೋಗುತ್ತವೆ; ಧರ್ಮ ಕಳೆದುಹೋದಾಗ ಅಧರ್ಮ ಇಡೀ ಕುಲವನ್ನು ಆವರಿಸುತ್ತದೆ.',
41: 'ಹೇ ಕೃಷ್ಣ, ಅಧರ್ಮ ಹರಡಿದಾಗ ಕುಲದ ಸ್ತ್ರೀಯರು ದಾರಿ ತಪ್ಪುತ್ತಾರೆ, ಅದರಿಂದ ಸಮಾಜದ ವ್ಯವಸ್ಥೆಯಲ್ಲಿ ಗೊಂದಲ ಉಂಟಾಗುತ್ತದೆ.',
42: 'ಈ ಗೊಂದಲ ಕುಲವನ್ನೂ ಕುಲನಾಶಕರನ್ನೂ ನರಕಕ್ಕೆ ಎಳೆಯುತ್ತದೆ, ಮತ್ತು ಪಿಂಡ ಹಾಗೂ ಜಲದ ತರ್ಪಣ ಸಿಗದೆ ಅವರ ಪಿತೃಗಳು ಪತನ ಹೊಂದುತ್ತಾರೆ.',
43: 'ಕುಲನಾಶಕರ ಈ ತಪ್ಪುಗಳಿಂದ ಸಮುದಾಯ ಮತ್ತು ಕುಲದ ಶಾಶ್ವತ ಧರ್ಮಗಳು ನಾಶವಾಗುತ್ತವೆ.',
44: 'ಹೇ ಜನಾರ್ದನ, ಕುಲಧರ್ಮ ನಾಶವಾದ ಜನರು ದೀರ್ಘಕಾಲ ನರಕದಲ್ಲಿ ವಾಸಿಸುತ್ತಾರೆ ಎಂದು ನಾವು ಕೇಳಿದ್ದೇವೆ.',
45: 'ಅಯ್ಯೋ! ರಾಜ್ಯಸುಖದ ಲೋಭದಿಂದ ನಮ್ಮವರನ್ನೇ ಕೊಲ್ಲಲು ಸಿದ್ಧರಾಗಿ, ನಾವು ಎಂಥ ದೊಡ್ಡ ಪಾಪ ಮಾಡಲು ಹೊರಟಿದ್ದೇವೆ!',
46: 'ನಾನು ಆಯುಧವಿಲ್ಲದೆ, ಪ್ರತಿಯಾಗಿ ಹೋರಾಡದೆ ನಿಂತಿರುವಾಗ, ಆಯುಧ ಹಿಡಿದ ಧೃತರಾಷ್ಟ್ರನ ಮಕ್ಕಳು ನನ್ನನ್ನು ಯುದ್ಧದಲ್ಲಿ ಕೊಂದರೆ ಅದೇ ನನಗೆ ಹೆಚ್ಚು ಒಳ್ಳೆಯದು."',
47: 'ಸಂಜಯ ಹೇಳಿದನು: ಯುದ್ಧಭೂಮಿಯಲ್ಲಿ ಹೀಗೆ ಹೇಳಿ, ದುಃಖದಿಂದ ಮನಸ್ಸು ಕುಸಿದ ಅರ್ಜುನ ಬಿಲ್ಲುಬಾಣಗಳನ್ನು ಕೆಳಗೆಸೆದು ರಥದ ಆಸನದಲ್ಲಿ ಕುಸಿದು ಕುಳಿತನು.',
}
